'use strict';
(()=>{
const {words,meta}=window.KOTOBA_DATA,E=window.KotobaEngine,Q=window.KotobaQuiz,$=s=>document.querySelector(s),byId=new Map(words.map(w=>[w.id,w]));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const priorityLabel={A:'A · 优先掌握',B:'B · 重点巩固',C:'C · 阅读识记'},viewNames={today:'今日学习',review:'间隔复习',library:'全部词库',mistakes:'易错与收藏',extreme:'极易错',grind:'狂刷模式',stats:'学习记录',about:'词库与筛选依据'};
let state=E.fresh(),storageOK=true,loadError=false,migrated=false;
try{const current=localStorage.getItem(E.KEY),legacy=!current&&E.LEGACY_KEYS.reduce((raw,key)=>raw||localStorage.getItem(key),null),raw=current||legacy;migrated=!!legacy;if(raw){try{const parsed=JSON.parse(raw);state=E.validate(parsed,new Set(byId.keys()));migrated=migrated||JSON.stringify(state.words)!==JSON.stringify(parsed.words);}catch(e){loadError=true;}}}catch(e){storageOK=false;}
let view='today',tab='card',session=null,revealed=false,kanaVisible=false,quiz=null,grindQuiz=null,query='',priority='all',lesson='all',listPage=0,mistakeFilter='all',pendingImport=null,toastTimer,previousQuizId=null,calendarDay=E.today(),calendarTimer;
const lessons=Array.from(new Set(words.map(w=>w.lesson?.split('-')[0]).filter(Boolean))).sort((a,b)=>a-b);
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function save(){state.savedAt=new Date().toISOString();try{localStorage.setItem(E.KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('浏览器未能保存进度，请先导出备份。');}updateSaveLabel();}
function updateSaveLabel(){$('#saveStatus').textContent=storageOK?'● 本机保存':'○ 未能保存';$('#saveStatus').style.color=storageOK?'':'#c48776';}
const sourceLabel=collection=>meta.collections?.[collection]?.label||(collection==='additional'?'新增词表':'原词表');
function verbWarningHTML(w){return w.pos==='一类动词'&&w.kana.endsWith('る')?'<div class="verb-warning">一类动词</div>':'';}
function sourceText(s){const label=sourceLabel(s.collection);return s.document||meta.collections?.[s.collection]?.document?`${label} · 原表第${s.number}项`:`${label} 第${s.page}页 · ${s.lesson?'第'+s.lesson+'课':'课次待补'}`;}
function src(w){return w.source==='exam'?'参照补充词':sourceText(w);}
function displayWord(w){return (w.quizWritten||w.word).replace(/（.*?）/g,'');}
function fmtDate(d){return new Date(d).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric'});}
function goto(v){if(!viewNames[v])v='today';view=v;listPage=0;document.querySelectorAll('.nav-item[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===v));document.title='拾词 · '+viewNames[v];if(location.hash!=='#'+v)history.replaceState(null,'','#'+v);render();}
function weekDays(){const now=Date.now(),arr=[];for(let i=6;i>=0;i--){const t=now-i*E.DAY,d=E.today(t);arr.push({day:d,label:['日','一','二','三','四','五','六'][new Date(d+'T00:00:00+08:00').getDay()],count:state.logs.filter(l=>l.day===d).length,isToday:i===0});}return arr;}
function progressPanel(){const c=E.counts(state),daily=E.dailyReadingStatus(words,state),passed=words.filter(w=>state.words[w.id]?.seen>0&&state.words[w.id].readingStreak>=5).length;return `<aside class="right-rail"><section class="panel"><h3>学习计划</h3><div class="goal-row"><span>今日新学</span><b>${c.newToday} / ${state.settings.newGoal}</b></div><div class="goal-row"><span>今日复习</span><b>${c.reviewToday} / ${state.settings.reviewGoal}</b></div><div class="goal-row"><span>今日读音</span><b>${daily.done} / ${daily.total}</b></div><div class="goal-row"><span>到期复习</span><b>${c.due}</b></div><div class="mini-line"></div><div class="goal-row"><span>累计已学</span><b>${c.learned}</b></div><div class="goal-row"><span>读音低频抽查</span><b>${passed}</b></div><button class="text-button" data-action="settings">调整计划与备份</button></section><section class="panel"><h3>${view==='review'?'复习规则':'训练规则'}</h3><p class="small muted">${view==='review'?'本组到期词随机以单词卡或读音题出现。熟词在抽查到期前使用单词卡；答对或点「认识了」完成本轮。':'每天先练昨天新背的全部词，再随机加入10个更早背过的词；历史词不足10个时按实际数量安排。'}</p><p class="small muted">当天答对一次即停止出读音题；错词练到选对。跨天首次连对5次后，按7、14、30天抽查；错后订正不计达标次数。读音累计错5次或词卡连点5次「再学一次」，加入「极易错」。</p><p class="small muted">复习在北京时间0点更新；单词卡与读音题随机混合。</p></section></aside>`;}
function bookOverview(){return '';}
function greeting(){const h=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'numeric',hourCycle:'h23'}).format(new Date()));return h<11?'早上好':h<14?'中午好':h<18?'下午好':'晚上好';}
function welcome(title,sub){return `<section class="welcome"><div><h1>${title}</h1><p>${sub}</p></div></section>`;}
function getSession(mode='mixed'){
 if(!session||session.mode!==mode||(session.calendarDay&&session.calendarDay!==E.today()&&session.index>=session.queue.length&&!(quiz?.review&&quiz.selected!==null))){
  const queue=E.queue(words,state,mode).map(w=>w.id);
  session={mode,queue:mode==='review'?Q.shuffle(queue):queue,index:0,done:0,startSize:queue.length,calendarDay:E.today()};revealed=false;quiz=null;
 }
 return session;
}
function current(mode){const s=getSession(mode);return byId.get(s.queue[s.index]);}
function emptyCard(mode){const c=E.counts(state),selected=E.filter(words,state.settings),unseen=selected.filter(w=>!state.words[w.id]?.seen).length;const isReview=mode==='review';let title=isReview?'到期的词，都复习好了':'这一组，已经记进去了';let copy=isReview?'复习每天北京时间0点更新，安排到期词，以及前一天读音答错或标记不熟悉的词。':`今天已新学 ${c.newToday} 词、复习 ${c.reviewToday} 词。可以休息一下，也可以自由练习。`;if(isReview&&c.due>0){title='今天的复习计划已完成';copy=`仍有 ${c.due} 词到期，可以继续复习，或调整范围与每日上限。`;}if(!selected.length){title='当前范围里没有单词';copy='请切换优先级或课次后再开始。';}return `<div class="empty"><div class="empty-glyph">好</div><h2>${title}</h2><p>${copy}</p><div class="button-row">${isReview&&c.due?'<button class="button primary" data-action="extraReview">再复习10个</button>':''}${!isReview&&unseen?'<button class="button primary" data-action="extra">再学10个新词</button>':''}<button class="button ${isReview?'primary':'secondary'}" data-action="${isReview?'goToday':'quiz'}">${isReview?'去学新词':'自由读音训练'}</button></div></div>`;}
function phraseHTML(w,limit=3){if(!w.phrases?.length)return '';return `<section class="linked-phrases"><div class="detail-label">联合记忆</div>${w.phrases.slice(0,limit).map(p=>`<div class="linked-phrase"><div class="phrase-jp" lang="ja">${esc(p.jp)}</div><div class="phrase-reading" lang="ja">${esc(p.kana)}</div><div class="phrase-meaning">${esc(p.meaning)}</div><div class="phrase-links">${p.words.map(x=>`<button class="phrase-word" data-action="detail" data-id="${x.id}" title="${esc(x.kana+' · '+x.meaning)}">${esc(x.word)}</button>`).join('<span>＋</span>')}</div></div>`).join('')}</section>`;}
function wordFormsHTML(w){const f=w.forms,base=f&&w.pos.includes('サ变')?displayWord(w)+'する':displayWord(w);if(!f)return `<div class="inline-word-type"><span class="detail-label">词形</span><span lang="ja">${esc(base)}</span><span>${esc(w.pos)}</span></div>`;const forms=[['基本形',base],...Object.entries({masu:'ます形',te:'て形',ta:'た形',nai:'ない形',potential:'可能形'}).filter(([key])=>f[key]).map(([key,label])=>[label,f[key]])];return `<section class="inline-forms" aria-label="词形与变形"><div class="detail-label">词形与变形 <span class="form-pos">${esc(w.pos)}</span></div><div class="conjugation">${forms.map(([label,value])=>`<div class="form-cell"><small>${label}</small><span lang="ja">${esc(value)}</span></div>`).join('')}</div><p class="form-caption">各形从基本形变化；サ变名词按「名词＋する」活用。</p></section>`;}
function completeSourcesHTML(w){const rows=[...new Set((w.sources||[]).filter(x=>x.collection!=='exam').map(sourceText))];return `<section class="card-provenance" aria-label="完整来源"><div class="source-list"><span class="detail-label">完整来源</span><span>${rows.length?rows.map(esc).join('；'):esc(src(w))}</span></div><div class="evidence">${esc(w.reason)}${w.examReference?'<br>'+esc(w.examReference):''}</div></section>`;}
function dictionaryHTML(w){return `<a class="text-button dictionary-link" href="https://www.weblio.jp/content/${encodeURIComponent(displayWord(w))}" target="_blank" rel="noopener noreferrer">外部词典核对 ↗</a>`;}
function wordCard(w,s){const a=state.words[w.id],star=!!a?.star;return `<article class="study-card${revealed?' is-revealed':''}"><div class="progress-line"><div style="width:${s.startSize?Math.min(100,s.done/s.startSize*100):0}%"></div></div><div class="card-meta"><div><span class="tag ${w.priority}">${priorityLabel[w.priority]}</span><span class="source">${src(w)}</span></div><div class="card-actions"><button class="icon-button ${star?'starred':''}" data-action="star" data-id="${w.id}" aria-label="${star?'取消收藏':'收藏单词'}">${star?'★':'☆'}</button><button class="icon-button" data-action="speak" data-id="${w.id}" aria-label="朗读单词">◖))</button></div></div><div class="word-core"><h2 lang="ja">${esc(displayWord(w))}</h2>${verbWarningHTML(w)}<div class="kana" lang="ja">${revealed||kanaVisible?esc(w.kana):'&nbsp;'}</div>${revealed?`<div class="word-meaning">${esc(w.meaning)}</div><span class="pos">${esc(w.pos)}</span>`:''}</div>${revealed?`<div class="card-detail"><div class="detail-label">搭配与易错提醒</div><p>${esc(w.note)}</p>${w.example?`<div class="example"><div class="jp" lang="ja">${esc(w.example.jp)}</div><div class="zh">${esc(w.example.zh)}</div></div>`:''}${wordFormsHTML(w)}${phraseHTML(w)}${completeSourcesHTML(w)}${dictionaryHTML(w)}</div>`:''}<div class="card-bottom" title="本组已点认识了的单词数 / 本组单词总数">本组 ${s.done} / ${s.startSize}</div></article>`;}
function nextReviewLabel(w){
 const a=state.words[w.id],now=Date.now(),stage=!a?.seen?0:a.lastReviewDay===E.today()?a.stage:Math.min(5,a.stage+1);
 const next=Math.min(E.reviewDue(now,E.INTERVALS[stage]),...(a?.readingStreak>=5&&a.readingDue>now?[a.readingDue]:[]),...(a?.troubleDays||[]).filter(d=>d>E.today()).map(d=>Date.parse(d+'T00:00:00+08:00')));
 const days=Math.round((next-E.dayStart(now))/E.DAY);return (days===1?'明日':days+'天后')+'0点复习';
}
function controls(w){return `<div class="study-controls">${!revealed?'<button class="button primary full" data-action="reveal">查看读音与释义 <kbd>空格</kbd></button>':`<div class="grade-grid"><button class="grade again" data-action="rate" data-grade="again">1 · 再学一次<small>隔1～2词后再练</small></button><button class="grade" data-action="rate" data-grade="hard">2 · 还不太熟<small>隔1～2词后再练</small></button><button class="grade good" data-action="rate" data-grade="good">3 · 认识了<small>${nextReviewLabel(w)}</small></button></div>`}</div><div class="shortcut-guide"><kbd>空格</kbd> 揭晓 <span> &nbsp; </span><kbd>1</kbd><kbd>2</kbd><kbd>3</kbd> 标记熟悉度 <span> &nbsp; </span><kbd>P</kbd> 发音</div>`;}
function reviewContent(s,w){
 // Keep answered feedback on screen until Next, even though its queue step is complete.
 if(quiz?.review&&quiz.selected!==null)return quizHTML(true);
 if(!w)return emptyCard('review');
 if(s.taskIndex!==s.index){
  s.taskIndex=s.index;revealed=false;quiz=null;
  s.taskKind=E.readingPlanned(state,w.id)&&(state.words[w.id]?.readingRetry||E.readingCheckDue(state.words[w.id])||(E.readingReady(state.words[w.id])&&Math.random()<.5))?'quiz':'card';
  if(s.taskKind==='quiz'){quiz=Q.createQuestion([w],state);quiz.review=true;}
 }
 return s.taskKind==='quiz'?quizHTML(true):wordCard(w,s)+controls(w);
}
function studyHTML(mode='mixed'){
 const s=getSession(mode),w=current(mode),review=mode==='review';
 return `<div class="study-layout"><section class="study-stage"><div class="section-bar study-toolbar"><div><h1 class="study-title">${review?'间隔复习':'今日单词'}</h1><p class="study-instruction">${review?'北京时间0点更新 · 单词卡与读音题随机混合':'全词库混合随机学习，先回忆，再查看答案。'}</p></div>${review?'':`<div class="switches"><button data-action="card" class="${tab==='card'?'active':''}">单词卡</button><button data-action="quiz" class="${tab==='quiz'?'active':''}">读音训练</button></div>`}</div>${review?reviewContent(s,w):tab==='quiz'?quizHTML():w?wordCard(w,s)+controls(w):emptyCard(mode)}<div class="session-banner"><span>${words.length} 项词汇 · 已学 ${E.counts(state).learned} 项</span><button class="text-button" data-action="range">选择学习范围</button></div>${bookOverview()}</section>${progressPanel()}</div>`;
}
function makeQuiz(){quiz=Q.createQuestion(E.dailyReadingPool(words,state),state,previousQuizId);if(quiz)previousQuizId=quiz.id;}
function quizHTML(review=false,grind=false){
 if(grind&&!grindQuiz){const w=E.nextGrindWord(words,state);if(w){grindQuiz=Q.questionForWord(w);save();}}
 if(!grind&&!quiz&&!review)makeQuiz();
 const question=grind?grindQuiz:quiz;
 if(grind&&!question)return `<div class="empty"><h2>${E.counts(state).learned?'狂刷已全部达标':'先学词，再来狂刷'}</h2><p>${E.counts(state).learned?'已背词都已连对5次。以后有词答错或标记不熟，会重新进入狂刷。':'先在今日学习里背单词，学过的词会自动进入这里。'}</p><button class="button primary" data-action="goToday">去学单词</button></div>`;
 const daily=E.dailyReadingStatus(words,state),learned=E.counts(state).learned,remaining=daily.remaining,passed=words.filter(w=>state.words[w.id]?.seen>0&&state.words[w.id].readingStreak>=5).length,nextCheck=Math.min(Infinity,...Object.values(state.words).filter(w=>w.seen>0&&w.readingDue>Date.now()).map(w=>w.readingDue));
 if(!question)return `<div class="empty"><h2>${learned?'本轮读音练习已完成':'先学词，再训练'}</h2><p>${learned?`今日读音 ${daily.done} / ${daily.total} 词。每天练昨天新背的全部词，再随机加入10个更早背过的词；历史词不足10个时按实际数量安排。今天新背的词明天再练。${Number.isFinite(nextCheck)?'下次读音练习：'+fmtDate(nextCheck)+'0点。':''}`:'今天新背的词将在明天进入读音训练。每天安排昨天新背的全部词，再随机加入10个更早背过的词。'}</p><button class="button primary" data-action="card">去学单词</button></div>`;
 const w=byId.get(question.id),answered=question.selected!==null,streak=(grind?state.words[w.id]?.grindStreak:state.words[w.id]?.readingStreak)||0,correct=answered&&question.selected===question.answer,lowFrequency=streak>=5,success=grind?(streak>=5?'狂刷连对5次 · 本词已移出狂刷':`狂刷连对 ${streak} / 5 · 后续轮次继续练`):lowFrequency?`已转低频抽查 · ${fmtDate(state.words[w.id].readingDue)}0点再见`:state.words[w.id].readingFailedDay===E.today()?'今日订正完成 · 今天不再出本词读音题':`今日完成 · 跨天连对${streak} / 5`;
 return `<div class="training-summary"><span>${grind?`第 ${state.grindSession.round} 轮 · 待达标 ${E.grindPool(words,state).length} 词`:review?`本组 ${session.done} / ${session.startSize} · 混合复习`:`今日读音 ${daily.done} / ${daily.total} · 待练 ${remaining}`}</span><span>${question.type==='kana'?'选假名':'选日语汉字'}</span></div><article class="study-card quiz-card${answered?' is-answered':''}"><div class="card-meta"><span class="small muted">${question.type==='kana'?'选择正确读音':'选择符合词义的日语写法'}${grind?`<span class="grind-errors">累计错 ${state.words[w.id]?.readingWrong||0} 次</span>`:''}</span><span class="streak-counter">${grind?'狂刷连对':'跨天连对'} ${streak} / 5</span></div><div class="word-core"><h2 lang="ja" class="${question.type==='kanji'?'kana-prompt':''}">${esc(question.prompt)}</h2>${verbWarningHTML(w)}<div class="quiz-hint">${esc(question.hint)}</div></div><div class="quiz-options">${question.options.map((a,i)=>`<button class="quiz-choice ${answered&&a===question.answer?'right':''} ${answered&&question.selected===a&&a!==question.answer?'wrong':''}" ${answered?'disabled':''} data-action="quizAnswer" data-answer="${esc(a)}">${i+1}. ${esc(a)}</button>`).join('')}</div>${answered?`<div class="quiz-feedback"><strong>${correct?(review?`本词本轮复习完成 · ${success}`:success):grind?'本词狂刷计数已归零，将在后续随机轮次再出现。':review?'本词计数已归零，稍后会再出现。':'本词计数已归零，从0重新开始。'}</strong><p><span lang="ja">${esc(displayWord(w))} · ${esc(w.kana)}</span><br>${esc(w.meaning)}<br>${esc(w.note)}</p>${phraseHTML(w,2)}<button class="text-button" data-action="speak" data-id="${w.id}">听正确读音</button></div>`:''}</article>${answered?`<button class="button primary full" style="margin-top:16px" data-action="nextQuiz">${review?'继续复习':'下一题'} <kbd>回车</kbd></button>`:''}<div class="shortcut-guide"><kbd>1</kbd>—<kbd>4</kbd> 选择答案　<kbd>回车</kbd> 下一题</div>`;
}
function grindHTML(){
 const pool=E.grindPool(words,state),learned=E.counts(state).learned;
 return `<div class="study-layout"><section class="study-stage"><div class="section-bar study-toolbar"><div><h1 class="study-title">狂刷模式</h1><p class="study-instruction">错题优先 · 已背词随机轮练 · 连对5次移出</p></div></div>${quizHTML(false,true)}<div class="session-banner"><span>只练已背词 · 不限数量与轮次</span></div></section><aside class="right-rail"><section class="panel"><h3>狂刷进度</h3><div class="goal-row"><span>累计已背</span><b>${learned}</b></div><div class="goal-row"><span>待达标</span><b>${pool.length}</b></div><div class="goal-row"><span>已连对5次</span><b>${learned-pool.length}</b></div><button class="text-button" data-action="settings">进度与备份</button></section><section class="panel"><h3>狂刷规则</h3><p class="small muted">已背词全库参加，不限数量。连对5次的词跳过；再次出错或词卡点不熟会重入。</p><p class="small muted">有错误或不熟记录的词优先；同组内随机，每轮每词一次。词量充足时至少穿插6题再重出。</p><p class="small muted">狂刷连对5次移出，错一次归零；累计错数不清零。只剩1词时继续练它。常规复习照常安排。</p></section></aside></div>`;
}
function filteredList(){return words.filter(w=>{const a=state.words[w.id];return (priority==='all'||w.priority===priority)&&(lesson==='all'||(lesson==='exam'?w.source==='exam':w.lesson?.split('-')[0]===lesson))&&(!query||[w.word,w.quizWritten||'',...(w.aliases||[]),...(w.acceptedWritten||[]),...(w.acceptedKana||[]),w.kana,w.meaning,w.pos,w.note].some(t=>t.includes(query)))&&(view!=='extreme'||a?.seen>0&&((a.readingWrong||0)>=5||(a.cardAgainMax||0)>=5))&&(view!=='mistakes'||(mistakeFilter==='star'?a?.star:mistakeFilter==='wrong'?a?.lapses>0:a?.star||a?.lapses>0));});}
function filtersHTML(){return `<div class="filters"><input class="search" id="wordSearch" type="search" placeholder="查找日语、假名或中文释义…" value="${esc(query)}" aria-label="搜索词库"><select id="priorityFilter" aria-label="优先级">${[['all','全部优先级'],['A','A · 优先掌握'],['B','B · 重点巩固'],['C','C · 阅读识记']].map(([v,l])=>`<option value="${v}" ${priority===v?'selected':''}>${l}</option>`).join('')}</select><select id="lessonFilter" aria-label="教材课次"><option value="all">全部课次</option>${lessons.map(l=>`<option value="${l}" ${lesson===l?'selected':''}>第${l}课</option>`).join('')}<option value="exam" ${lesson==='exam'?'selected':''}>回忆卷补充</option></select>${view==='mistakes'?`<select id="mistakeFilter" aria-label="易错或收藏">${[['all','易错与收藏'],['wrong','只看易错'],['star','只看收藏']].map(([v,l])=>`<option value="${v}" ${mistakeFilter===v?'selected':''}>${l}</option>`).join('')}</select>`:''}</div>`;}
function tableHTML(){const list=filteredList(),size=25,max=Math.max(1,Math.ceil(list.length/size));listPage=Math.min(listPage,max-1);const slice=list.slice(listPage*size,(listPage+1)*size);return `<div class="section-bar"><span class="list-count">找到 ${list.length} 项 · 点击单词查看读音、用法与词形</span><button class="text-button" data-action="csv">↓ 导出完整词库</button></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>单词 / 假名</th><th>中文释义</th><th>优先级</th><th>来源</th><th>${view==='extreme'?'易错记录':'学习状态'}</th><th>收藏</th></tr></thead><tbody>${slice.map(w=>{const a=state.words[w.id];return `<tr data-id="${w.id}" tabindex="0" role="button" aria-label="查看${esc(w.word)}"><td><strong lang="ja">${esc(w.quizWritten||w.word)}</strong>${verbWarningHTML(w)}<span class="reading" lang="ja">${esc(w.kana)}</span></td><td>${esc(w.meaning)}<span class="reading">${esc(w.pos)}</span></td><td><span class="tag ${w.priority}">${priorityLabel[w.priority]}</span></td><td><span class="small">${src(w)}</span></td><td><span class="small">${view==='extreme'?[a.readingWrong?`读音累计错 ${a.readingWrong} 次`:'',a.cardAgainMax?`词卡「再学一次」最高连点 ${a.cardAgainMax} 次`:''].filter(Boolean).join('；'):`${!a?.seen?'未学习':E.isDue(a,Date.now(),state)?'待复习':a.relearning?'待巩固':a.stage>=3?'较熟悉':'已学习'}${a?.lapses?` · 易错${a.lapses}次`:''}`}</span></td><td><button class="icon-button ${a?.star?'starred':''}" data-action="star" data-id="${w.id}" aria-label="${a?.star?'取消收藏':'收藏'}${esc(w.word)}">${a?.star?'★':'☆'}</button></td></tr>`}).join('')}</tbody></table></div><div class="pagination"><span>第 ${listPage+1} / ${max} 页</span><div class="button-row"><button class="button secondary" data-action="prevPage" ${listPage===0?'disabled':''}>← 上一页</button><button class="button secondary" data-action="nextPage" ${listPage>=max-1?'disabled':''}>下一页 →</button></div></div>`:view==='extreme'?'<div class="empty"><h2>还没有符合条件的极易错词</h2><p>读音题累计答错5次，或词卡连续点5次「再学一次」，会自动出现在这里。</p></div>':'<div class="empty"><h2>这里还没有单词</h2><p>试试更换搜索条件。学习中点「再学一次」，或收藏的词，会出现在这里。</p></div>'}`;}
function libraryHTML(){const isMistake=view==='mistakes',isExtreme=view==='extreme';return `${welcome(isExtreme?'极易错':isMistake?'易错与收藏':'全部词库',isExtreme?'读音累计错5次，或词卡连续点5次「再学一次」，自动加入；分别保存两种易错记录。':isMistake?'把易忘的、易混的、想留下的，放在这里慢慢熟悉。':`${words.length} 项 · 四套词表已合并去重`)}${filtersHTML()}<div id="wordTable">${tableHTML()}</div>`;}
function statsHTML(){const c=E.counts(state),days=weekDays(),max=Math.max(1,...days.map(d=>d.count));return `${welcome('学习记录','只记录真实学习，不预填打卡。复习间隔会随你的熟悉度变化。')}<div class="stat-grid">${[[c.learned,'累计学过的词'],[c.mastered,'较熟悉 · 至少14天间隔'],[c.due,'当前到期复习'],[new Set(state.logs.map(l=>l.day)).size,'有练习记录的天数']].map(([n,t])=>`<section class="panel"><strong>${n}</strong><span>${t}</span></section>`).join('')}</div><div class="about-grid"><section class="panel"><h3>近七天练习次数</h3><div class="chart-bars">${days.map(d=>`<div class="bar"><strong>${d.count}</strong><div style="height:${d.count/max*110}px" title="${d.day} · ${d.count}次"></div><span>${d.day.slice(5)}</span></div>`).join('')}</div><p class="muted small">每次标记或答题算一次练习，同一个词可能出现多次。</p></section><section class="panel"><h3>词库熟悉度</h3>${['A','B','C'].map(p=>{const total=words.filter(w=>w.priority===p).length,n=words.filter(w=>w.priority===p&&state.words[w.id]?.seen>0).length;return `<div class="goal-row"><span>${priorityLabel[p]}</span><b>${n} / ${total}</b></div><div class="progress-line"><div style="width:${n/total*100}%"></div></div>`}).join('')}<p class="muted small" style="margin-top:24px">读音训练按不同日期的首次作答计数；当天答对后停止出题，跨天连对5次转低频抽查，答错归零。单词卡的间隔复习照常安排。</p><button class="text-button" data-action="settings">导出学习进度 ↗</button></section></div><div class="info-box">记忆安排：「再学一次」和「还不太熟」都会隔1～2个词继续练，不限次数，直到点「认识了」。本组只剩待巩固词时，会继续练这些词；刷新后也会保留。点「认识了」后，再按1、3、7、14、30、60天安排复习。复习在到期日北京时间0点解锁；前一天读音答错、点过「还不太熟」或「再学一次」的词也会加入，即使当天后来答对。复习中的词卡和读音题随机混合。</div>`;}
function aboutHTML(){return `${welcome('词库说明','按基础程度、搭配和活用的迁移价值分级，参考卷只用于判断题型。')}<section class="panel"><h3>词库范围</h3><p class="muted">${words.length}项，包含原词表、新增词表、两套扩展词表、两份Word补充词表及少量参照补充词。已对照45张词表照片及两份Word补齐可辨认词项。本轮三页续表151条，去重新增146项；最早10页重新核对569条索引记录，补漏183项。合并重复来源；同音异义、同形异读分别保留。照片来源各自保留实印页码，不因页码相同而混淆。无法辨认的课次留空。两份Word共核对${meta.documentImports.sourceRows}条有词形的来源，去重后补入${meta.documentImports.added}项，按原表项号标注；重复练习表不重复录入。初级练习表第290项缺少词形和读音，暂不猜填。</p><p class="muted">A优先掌握，B重点巩固，C阅读识记；不按单套卷的出现次数预测考试概率。释义取常用义，词卡保留搭配与活用。已整理${meta.phraseCount}组联合记忆短语，覆盖${meta.wordsWithPhrases}项词条。</p><h3>词类提醒</h3><p class="muted">以る结尾的一类动词，会在单词下方显示红字「一类动词」，例如帰る、入る、走る。不能只看る结尾就按二类动词变形。</p><h3>读音与字形训练</h3><p class="muted">每天读音训练为昨天新背的全部词，加随机10个更早背过的词，不设30词上限。例如昨天新背25词，今天就是25＋10＝35词；历史词不足10个时按实际数量安排。今日名单固定保存，刷新不换词。当日新背的词次日参加训练，错题重练不另占名额。点选答案后，无论对错都自动朗读目标词的正确读音；选答案前不播放。读音已转低频的词只在抽查到期后入选，不受课次和等级筛选影响。「看汉字选假名」与「看假名选汉字」随机混合；纯假名词以中文提示选假名。两种题型共同累计：每词当天答对一次后不再出读音题，未满5次则在次日0点重新进入可抽取范围；答错继续练到答对，但当天订正不计入达标次数。不同日期首次作答连续正确5次后改为7天后抽查；继续答对后依次延长到14天、30天，此后保持30天。错一次，该词归零并恢复正常训练频率。读音累计错5次或词卡连续点5次「再学一次」，加入「极易错」。读音累计错误数不因答对而清零；词卡点「认识了」或「还不太熟」会中断连点计数，已达门槛的易错记录保留。间隔复习每天北京时间0点更新，混合安排词卡与读音题；熟词在读音抽查到期前使用词卡复习，抽查到期后重新出读音题。答对或点「认识了」完成本轮，答错或不熟则稍后重现。前一天出错或点过不熟悉的词，即使后来答对，次日仍安排复习。</p><p class="muted">假名干扰项围绕同一读音改动长音、促音、拗音或清浊音；汉字干扰项采用目标词的形近字。错误选项是用于辨析的干扰写法，不是新增词条；同形异读及可接受的异体写法会避开。汉字题提供词义，防止同音词多解。</p><h3>狂刷模式</h3><p class="muted">只练已经背过的词，有错误或不熟记录的词优先，同组内随机；全部使用读音与字形选择题，两种方向随机。每词在狂刷连对5次后移出，错一次归零。按随机轮次无限循环，每轮每词一次，换轮重新打乱；有多个词时避免相邻重复。每题标注累计读音错误次数，包含普通训练与狂刷。狂刷连对次数、随机队列和错误总数会随备份保存；普通读音训练的跨天计数与间隔复习照常进行。</p><h3>进度</h3><p class="muted">保存在当前浏览器，换设备可导入导出备份。旧版背词进度会保留；旧读音记录按连续答对、遇错归零的顺序迁移。朗读使用设备的日语合成语音。</p></section><details class="panel"><summary>参考卷疑误与核对来源</summary>${meta.corrections.map(x=>`<div class="correction"><b>第${x.q}题 · ${esc(x.issue)}</b><p>${esc(x.fix)}</p></div>`).join('')}${meta.sources.map(x=>`<p class="small muted">${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a>`:esc(x.title)}：${esc(x.description)}</p>`).join('')}</details><button class="button secondary" data-action="csv">下载完整词表</button>`;}
function ensureReadingPlan(){const old=state.readingPlan;E.dailyReadingPlan(words,state);if(old!==state.readingPlan&&!loadError)save();}
function render(){ensureReadingPlan();const y=window.scrollY,studying=['today','review','grind'].includes(view);$('#main').classList.toggle('study-mode',studying);$('#dueNav').textContent=E.counts(state).due;$('#extremeNav').textContent=E.extremePool(words,state).length;$('#grindNav').textContent=E.grindPool(words,state).length;$('#main').innerHTML=view==='today'?studyHTML():view==='review'?studyHTML('review'):view==='grind'?grindHTML():['library','mistakes','extreme'].includes(view)?libraryHTML():view==='stats'?statsHTML():aboutHTML();updateSaveLabel();window.scrollTo(0,studying?0:y);}
function detail(id){const w=byId.get(id);if(!w)return;const f=w.forms;$('#detailContent').innerHTML=`<div class="detail-word" lang="ja">${esc(displayWord(w))}</div>${verbWarningHTML(w)}<div class="detail-reading" lang="ja">${esc(w.kana)}</div><div class="detail-meaning">${esc(w.meaning)}</div><div style="text-align:center"><span class="tag ${w.priority}">${priorityLabel[w.priority]}</span> <span class="pos">${esc(w.pos)}</span></div><div class="note-block">${esc(w.note)}</div>${f?`<div class="conjugation">${Object.entries({masu:'ます形',te:'て形',ta:'た形',nai:'ない形',potential:'可能形'}).filter(([k])=>f[k]).map(([k,l])=>`<div class="form-cell"><small>${l}</small><span lang="ja">${esc(f[k])}</span></div>`).join('')}</div><p class="muted small" style="margin-top:10px">变形从基本形直接生成；サ变名词显示「名词＋する」的形式。</p>`:''}${phraseHTML(w,12)}<div class="detail-footer">${(w.sources||[]).filter(x=>x.collection!=='exam').map(sourceText).join('<br>')||src(w)}<br>${esc(w.reason)}${w.examReference?'<br>'+esc(w.examReference):''}</div><div class="button-row"><button class="button primary" data-action="speak" data-id="${w.id}">朗读单词</button><a class="button secondary" href="https://www.weblio.jp/content/${encodeURIComponent(displayWord(w))}" target="_blank" rel="noopener noreferrer">外部词典核对 ↗</a></div>`;if(!$('#detailDialog').open)$('#detailDialog').showModal();}
function star(id){let a=state.words[id];if(!a)state.words[id]=a={stage:0,due:0,seen:0,lapses:0,star:false,learnedOn:E.today()};a.star=!a.star;save();render();toast(a.star?'已收藏，下次在「易错与收藏」见。':'已取消收藏。');}
function speak(id){const w=byId.get(id);if(!w)return;if(!('speechSynthesis'in window)){toast('当前浏览器不支持朗读，请使用 Safari、Chrome 或 Edge。');return;}const synth=window.speechSynthesis;const voice=synth.getVoices().find(v=>v.lang.startsWith('ja'));if(!voice){toast('设备暂未提供日语语音，请在系统语音设置中添加日语。');return;}synth.cancel();const u=new SpeechSynthesisUtterance(w.kana);u.lang='ja-JP';u.voice=voice;u.rate=.82;u.onerror=()=>toast('朗读未能播放，请检查系统日语语音。');synth.speak(u);}
function settings(){ $('#newGoal').value=state.settings.newGoal;$('#reviewGoal').value=state.settings.reviewGoal;$('#backupInfo').textContent=state.savedAt?'上次保存：'+new Date(state.savedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'还没有学习记录。';$('#settingsDialog').showModal();}
function download(text,name,type){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportState(){download(JSON.stringify({...state,exportedAt:new Date().toISOString(),dataVersion:meta.version},null,2),'shici-progress-'+E.today()+'.json','application/json');}
function csv(){const rows=[['单词','假名','中文','词性','优先级','教材课次','教材页码','来源','参考题号','用法提醒','联合记忆短语'],...words.map(w=>[w.quizWritten||w.word,w.kana,w.meaning,w.pos,w.priority,w.lesson||'',w.page||'',w.source==='exam'?'参照补充词':sourceLabel(w.collection),w.questions.join('、'),w.note,(w.phrases||[]).map(p=>p.jp+'（'+p.meaning+'）').join('；')])];download('\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'shici-vocabulary-'+E.today()+'.csv','text/csv;charset=utf-8');}
function range(){const old=$('#rangeDialog');if(old)old.remove();const d=document.createElement('dialog');d.id='rangeDialog';d.innerHTML=`<form method="dialog" class="dialog-head"><h2>选择学习范围</h2><button class="icon-button" aria-label="关闭">✕</button></form><div class="dialog-body"><p class="muted">全词库混合随机抽取，不按五十音或课次分批。选择范围后，也会在范围内随机安排。切换范围不会删除已学进度。</p><div class="form-grid"><label>优先级<select id="studyPriority">${[['all','全部优先级'],['A','A · 优先掌握'],['B','B · 重点巩固'],['C','C · 阅读识记']].map(([v,l])=>`<option value="${v}" ${state.settings.priority===v?'selected':''}>${l}</option>`).join('')}</select></label><label>教材课次<select id="studyLesson"><option value="all">全部课次</option>${lessons.map(l=>`<option value="${l}" ${state.settings.lesson===l?'selected':''}>第${l}课</option>`).join('')}<option value="exam" ${state.settings.lesson==='exam'?'selected':''}>回忆卷补充</option></select></label></div><button class="button primary full" id="saveRange">开始这一范围</button></div>`;document.body.append(d);$('#saveRange').onclick=()=>{state.settings.priority=$('#studyPriority').value;state.settings.lesson=$('#studyLesson').value;save();session=null;quiz=null;d.close();render();toast('已切换学习范围。');};d.showModal();}
const actions={
 reveal(){if(revealed)return;const w=current(view==='review'?'review':'mixed');if(!w)return;revealed=true;render();speak(w.id);},
 rate(el){const s=getSession(view==='review'?'review':'mixed'),w=current(s.mode);if(!revealed||!w)return;const grade=el.dataset.grade;E.rate(state,w.id,grade);E.advanceSession(s,grade);revealed=false;save();render();},
 star(el){star(el.dataset.id)},speak(el){speak(el.dataset.id)},detail(el){detail(el.dataset.id)},settings,range,csv,
 card(){tab='card';render()},quiz(){tab='quiz';render()},
 quizAnswer(el){
  const grind=view==='grind',q=grind?grindQuiz:quiz;if(!q||q.selected!==null)return;
  if(!grind&&!E.readingPlanned(state,q.id)){quiz=null;render();return;}
  const id=q.id,correct=el.dataset.answer===q.answer;
  if(grind&&!E.recordGrind(state,id,correct,q.type)){grindQuiz=null;render();return;}
  q.selected=el.dataset.answer;
  if(!grind){E.recordReading(state,id,correct,q.type);if(q.review){E.rate(state,id,correct?'good':'hard',Date.now(),'reading');if(!correct){state.words[id].reviewPending=true;state.words[id].readingRetry=true;}E.advanceSession(session,correct?'good':'hard');}}
  save();render();speak(id);
 },
 nextQuiz(){if(view==='grind')grindQuiz=null;else quiz=null;render()},
 goToday(){tab='card';session=null;goto('today')},extra(){const arr=E.shuffle(E.filter(words,state.settings).filter(w=>!state.words[w.id]?.seen)).slice(0,10);session={mode:view==='review'?'review':'mixed',queue:arr.map(w=>w.id),index:0,done:0,startSize:arr.length};revealed=false;render();},
 extraReview(){const arr=E.shuffle(E.filter(words,state.settings).filter(w=>E.isDue(state.words[w.id],Date.now(),state))).sort((a,b)=>state.words[a.id].due-state.words[b.id].due).slice(0,10);session={mode:'review',queue:Q.shuffle(arr.map(w=>w.id)),index:0,done:0,startSize:arr.length,calendarDay:E.today()};revealed=false;quiz=null;render();},
 prevPage(){listPage--;$('#wordTable').innerHTML=tableHTML()},nextPage(){listPage++;$('#wordTable').innerHTML=tableHTML()}
};
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(button){if(button.disabled)return;const f=actions[button.dataset.action];if(f)f(button);return;}const nav=e.target.closest('[data-view]');if(nav){goto(nav.dataset.view);return;}const tr=e.target.closest('tr[data-id]');if(tr)detail(tr.dataset.id);});
document.addEventListener('input',e=>{if(e.target.id==='wordSearch'){query=e.target.value.trim();listPage=0;$('#wordTable').innerHTML=tableHTML();}});
document.addEventListener('change',e=>{if(['priorityFilter','lessonFilter','mistakeFilter'].includes(e.target.id)){if(e.target.id==='priorityFilter')priority=e.target.value;if(e.target.id==='lessonFilter')lesson=e.target.value;if(e.target.id==='mistakeFilter')mistakeFilter=e.target.value;listPage=0;$('#wordTable').innerHTML=tableHTML();}});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey||e.target.matches('input,select,textarea'))return;if(e.target.closest('tr[data-id]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();detail(e.target.closest('tr').dataset.id);return;}if(!['today','review','grind'].includes(view))return;if(view==='grind'||(view==='review'?quiz?.review:tab==='quiz')){const q=view==='grind'?grindQuiz:quiz;if(q&&q.selected===null&&/^[1-4]$/.test(e.key)){e.preventDefault();actions.quizAnswer({dataset:{answer:q.options[Number(e.key)-1]}});}else if(e.key==='Enter'&&q&&q.selected!==null){e.preventDefault();actions.nextQuiz();}return;}const w=current(view==='review'?'review':'mixed');if(!w)return;if(e.code==='Space'){e.preventDefault();if(!revealed)actions.reveal();}else if(revealed&&/^[1-3]$/.test(e.key)){e.preventDefault();actions.rate({dataset:{grade:['again','hard','good'][Number(e.key)-1]}});}else if(e.key.toLowerCase()==='p'){e.preventDefault();speak(w.id);}});
$('#settingsButton').onclick=settings;
$('#helpButton').onclick=()=>toast('空格揭晓 · 1/2/3标记 · P朗读；读音训练用1—4选答案。');
$('#saveSettings').onclick=()=>{const a=Number($('#newGoal').value),b=Number($('#reviewGoal').value);if(!Number.isInteger(a)||a<1||a>100||!Number.isInteger(b)||b<1||b>200){toast('新词请输入1—100，复习请输入1—200之间的整数。');return;}state.settings.newGoal=a;state.settings.reviewGoal=b;save();session=null;$('#settingsDialog').close();render();toast('学习计划已保存。');};
$('#exportButton').onclick=exportState;$('#downloadWords').onclick=csv;
$('#importFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>10000000)throw Error('备份文件过大，请选择小于10MB的JSON。');pendingImport=E.validate(JSON.parse(await f.text()),new Set(byId.keys()));const c=E.counts(pendingImport);$('#importSummary').textContent=`备份包含 ${c.learned} 个学过的词、${pendingImport.logs.length} 条练习记录。`;$('#settingsDialog').close();$('#importDialog').showModal();}catch(err){toast(err.message||'无法读取这个备份。');}};
$('#cancelImport').onclick=()=>{pendingImport=null;$('#importDialog').close();};$('#confirmImport').onclick=()=>{if(!pendingImport)return;exportState();state=pendingImport;pendingImport=null;session=null;quiz=null;grindQuiz=null;save();$('#importDialog').close();render();toast('备份已导入，之前的进度也已下载备份。');};
if('speechSynthesis'in window)window.speechSynthesis.getVoices();
window.addEventListener('hashchange',()=>goto(location.hash.slice(1)));
window.addEventListener('storage',e=>{if(e.key===E.KEY&&e.newValue){try{state=E.validate(JSON.parse(e.newValue),new Set(byId.keys()));session=null;quiz=null;grindQuiz=null;render();toast('已同步当前浏览器其他标签页的进度。');}catch(err){toast('其他标签页的进度无法载入，请导出备份。');}}});
function syncCalendar(){
 const day=E.today();if(day!==calendarDay){calendarDay=day;if(quiz&&quiz.selected===null){quiz=null;if(session)delete session.taskIndex;}if(session&&session.index>=session.queue.length&&!(quiz?.review&&quiz.selected!==null)){session=null;quiz=null;revealed=false;}render();}
 else{$('#dueNav').textContent=E.counts(state).due;$('#extremeNav').textContent=E.extremePool(words,state).length;$('#grindNav').textContent=E.grindPool(words,state).length;}
 clearTimeout(calendarTimer);calendarTimer=setTimeout(syncCalendar,E.reviewDue()-Date.now()+30);
}
window.addEventListener('pageshow',syncCalendar);
window.addEventListener('focus',syncCalendar);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncCalendar();});
goto(viewNames[location.hash.slice(1)]?location.hash.slice(1):'today');
syncCalendar();
if(migrated&&!loadError)save();
if(loadError)setTimeout(()=>toast('旧进度格式有异常，尚未覆盖。请先导出或检查原有备份。'),300);
})();
